-- 概览与告警列表查询索引：幂等创建，不改写历史数据。
SET @sql := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='po_contents' AND index_name='po_contents_game_collected_idx')=0, 'ALTER TABLE po_contents ADD INDEX po_contents_game_collected_idx (game_id, collected_at, is_deleted)', 'SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='po_contents' AND index_name='po_contents_source_collected_idx')=0, 'ALTER TABLE po_contents ADD INDEX po_contents_source_collected_idx (source_id, collected_at, is_deleted)', 'SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
-- source_id is absent from some legacy po_alerts schemas; only create this optional index when available.
SET @sql := IF((SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name='po_alerts' AND column_name='source_id')=1 AND (SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='po_alerts' AND index_name='po_alerts_source_status_created_idx')=0, 'ALTER TABLE po_alerts ADD INDEX po_alerts_source_status_created_idx (source_id, status, created_at, id)', 'SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql := IF((SELECT COUNT(*) FROM information_schema.statistics WHERE table_schema=DATABASE() AND table_name='po_alerts' AND index_name='po_alerts_status_created_idx')=0, 'ALTER TABLE po_alerts ADD INDEX po_alerts_status_created_idx (status, created_at, id)', 'SELECT 1'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
